// ---- Fleet Pulse v2 — the schema-2 contract ------------------------------
// status-data.json is GENERATED by scripts/status-build.mjs from STATUS.yaml
// (+ launches/<domain>/ ledgers). STATUS.yaml is the truth; this file only
// describes the generated view's shape. HARD GATE 6 binds: every field here
// is machine-derived; a fact that cannot be derived arrives as null / [] and
// renders as its honest absence — never a guess.

export type MilestoneState = "done" | "in-review" | "next" | "pending";

export type OsMilestone = {
  id: "M0" | "M1" | "M2" | "M3" | "M4";
  label: string;
  state: MilestoneState;
};

export type OsBlock = {
  milestone: string;
  milestones: OsMilestone[];
  strict_residues: number;
  unacked_directives: number;
  open_questions: number;
  decisions: number;
  tests: { pass: number; total: number } | null;
};

export type GateStatus = "approved" | "pending" | "changes" | "none";

export type FrontGate = { gate: string; status: GateStatus };

export type Vector = {
  site_class: string;
  business_model: string;
  asset_situation: string;
  entity_register: string;
  platform: string;
};

export type Evidence = {
  go_science: number;
  beauty: number;
  design_review_pre: number;
  design_review_post: number;
  audits: number;
  checklists: boolean;
};

export type Site2 = {
  name: string;
  entity: string;
  stage: string;
  phase: number | null;
  owner: string | null;
  blocker: string | null;
  updated: string | null;
  preview_url?: string | null;
  live_url?: string | null;
  vector: Vector | null;
  /** From launches/<domain>/approvals.yaml. [] = no ledger = gate UNARMED. */
  front_gates: FrontGate[];
  evidence: Evidence;
  /** Names actually present in the blocker text — else []. Never inferred. */
  waiting_on: string[];
};

export type Snapshot2 = {
  schema: 2;
  generated: string; // IST to the second
  generated_utc: string;
  os: OsBlock;
  sites: Site2[];
};

/** Runtime guard: only render the v2 board on data that declares schema: 2. */
export function isSchema2(data: unknown): data is Snapshot2 {
  return (
    typeof data === "object" &&
    data !== null &&
    (data as { schema?: unknown }).schema === 2 &&
    Array.isArray((data as { sites?: unknown }).sites) &&
    typeof (data as { os?: unknown }).os === "object" &&
    (data as { os?: unknown }).os !== null
  );
}
